try { W.pvShares = JSON.parse(localStorage.getItem("torino-pv-shares") || "{}"); if(!W.pvShares||typeof W.pvShares!=="object")W.pvShares={}; W.pvShares=Object.fromEntries(Object.entries(W.pvShares).filter(([k,v])=>k.startsWith("L219/")&&(v===null||(typeof v==="number"&&Number.isFinite(v)&&v>=0&&v<=100)))); } catch (_) {}
const tr = (it, en) => W.lang === "it" ? it : en;
const number = (n, d = 0) => n == null || !Number.isFinite(+n) ? "—" : (+n).toLocaleString(W.lang === "it" ? "it-IT" : "en-GB", { maximumFractionDigits: d });
const badge = (text, cls = "") => `<span class="evidence ${cls}">${esc(text)}</span>`;
