const baseOriginals=new WeakMap();
function translateBase(){
  const pairs=Object.entries(BASE_TRANSLATIONS).sort((a,b)=>b[0].length-a[0].length);
  const convert=s=>{if(W.lang==="it")return s;let out=s; // Whole messages first, then a small set of dynamic fragments.
    if(BASE_TRANSLATIONS[s.trim()])return s.replace(s.trim(),BASE_TRANSLATIONS[s.trim()]);
    for(const [it,en]of pairs){if(it.length>=9||["piani","ingressi","edifici","fam.","Ingressi","Edifici","Piani"].includes(it))out=out.split(it).join(en);}return out;};
  const roots=[...document.querySelectorAll('[data-view]:not([data-view="energy"]):not([data-view="units"])'),$("legend"),$("panelTitle"),$("drawbar"),$("loading"),$("toast"),document.querySelector(".actionbar"),$("drawTop"),$("panelClose"),$("q"),document.querySelector(".leaflet-control-zoom")];
  for(const root of roots){if(!root)continue;const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);let node;while((node=walker.nextNode())){if(node.parentElement?.closest(".public-enrichment"))continue;const old=baseOriginals.get(node);const src=old&&node.nodeValue===old.result?old.source:node.nodeValue;const result=convert(src);baseOriginals.set(node,{source:src,result});if(node.nodeValue!==result)node.nodeValue=result;}
    for(const el of [root,...root.querySelectorAll("[title],[placeholder],[aria-label]")])for(const attr of ["title","placeholder","aria-label"]){if(["units","energy"].includes(el.dataset.panel)||!el.hasAttribute(attr))continue;const key=`data-i18n-${attr}`;const src=el.getAttribute(key)||el.getAttribute(attr);el.setAttribute(key,src);const value=convert(src);if(el.getAttribute(attr)!==value)el.setAttribute(attr,value);}}
}
new MutationObserver(()=>translateBase()).observe($("panel"),{childList:true,subtree:true});

let workspaceLoad=null;
function loadWorkspace(){return workspaceLoad??=(async()=>{
  try{
    const getFile=async path=>{const r=await fetch(`data/${path}`);if(!r.ok)throw Error(`${path}: HTTP ${r.status}`);return r.json();};
    [W.census,W.solar,W.benchmark,W.apes,W.grid]=await Promise.all(["census2023.json","solar.json","demand_benchmark.json","ape_units.json","grid_areas.geojson"].map(getFile));
    W.assumptions.householdKwh=W.benchmark.annual_sum_monthly_kwh;W.assumptions.yieldKwh=W.solar.scenarios.south.totals.E_y;
    for(const b of BLD){const c=W.census.buildings[String(b.p.bld_id)];if(c)Object.assign(b.p,{census_section_2021:c.section_id,census_status:c.status,dwellings_2023:c.dwellings,households_2023:c.households});
      // Expose building query without stealing normal parcel/entrance clicks.
    }
    for(const o of LOTS){const bs=(bldByFp.get(o.p.foglio_particella)||[]).filter(b=>b.p.sul_res_m2>0);const complete=bs.length>0&&bs.every(b=>b.p.census_status==="allocated_2023");o.p.dwellings_2023=complete?bs.reduce((s,b)=>s+b.p.dwellings_2023,0):null;o.p.households_2023=complete?bs.reduce((s,b)=>s+b.p.households_2023,0):null;o.p.census_status=complete?"allocated_2023":bs.length?"incomplete_coverage":"non_residential";}
    MODES.units2023={title:"",key:"dwellings_2023",hint:"",ramp:["#eff3ff","#bdd7e7","#6baed6","#3182bd","#08519c"],cls:[[0.00001,5,"≤5"],[5,15,"5–15"],[15,40,"15–40"],[40,100,"40–100"],[100,1e9,">100"]],none:""};
    const unitMode=document.createElement("button");unitMode.id="modeUnits2023";unitMode.type="button";unitMode.dataset.mode="units2023";$("modes").prepend(unitMode);mode="units2023";document.querySelectorAll("#modes button").forEach(b=>b.setAttribute("aria-pressed",String(b.dataset.mode===mode)));restyleLots();
    const gridLayer=L.geoJSON(W.grid,{pane:"sez",renderer:R.sez,style:{color:"#7b54a3",weight:2,dashArray:"8 4",fillOpacity:0.025},attribution:"GSE · Aree Convenzionali 2025–2027",onEachFeature:(f,l)=>l.bindTooltip(`${esc(f.properties.COD_AC)} · ${esc(f.properties.TXT1)}`)});
    const label=document.createElement("label");label.className="switch";label.innerHTML=`<span id="gridLabel">GSE · ${tr("Aree cabine primarie 2025","Primary-substation areas 2025")}</span><input type="checkbox" id="gridToggle">`;document.querySelector('[data-view="livelli"] .block').append(label);$("gridToggle").onchange=e=>e.target.checked?gridLayer.addTo(map):map.removeLayer(gridLayer);
    for(const ent of ENTS){const ll=ent.layer.getLatLng();ent.p.grid_areas_2025=W.grid.features.filter(f=>turf.booleanPointInPolygon([ll.lng,ll.lat],f)).map(f=>f.properties.COD_AC).join("; ");}
    W.ready=true;renderChrome();renderDetailsIfSelected();renderEnergy();renderUnits();if(W.tab!=="map")renderPage();
  }catch(err){footer.textContent=tr("Impossibile caricare i nuovi dati: ","Unable to load added sources: ")+err.message;footer.setAttribute("role","alert");workspaceLoad=null;throw err;}
})();}
